<template>
	<view class="charm-page">
		<view class="charm-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="header-row">
				<view class="back-button" @click="goBack"><view class="back-arrow" /></view>
				<text class="header-title">我的魅力</text>
				<view class="header-space" />
			</view>
		</view>
		<view class="charm-hero">
			<view class="hero-sun sun-one" />
			<view class="hero-sun sun-two" />
			<view class="hero-top-row">
				<view>
					<text class="hero-kicker">被看见的温柔</text>
					<view class="level-pill">{{ summary.level.name }}</view>
				</view>
				<text class="withdraw-threshold-tip">满 {{ withdrawal.minimumValue }} 可提现</text>
			</view>
			<view class="hero-value-row"><text class="hero-heart">♥</text><text class="hero-value">{{ summary.balance }}</text></view>
			<text class="hero-copy">{{ summary.level.description }}</text>
			<view class="hero-progress-card">
				<view class="progress-meta"><text>成长进度</text><text>{{ summary.level.progress }}%</text></view>
				<view class="progress-track"><view class="progress-value" :style="progressStyle" /></view>
				<text v-if="summary.level.nextLevel" class="next-level">再收获 {{ summary.level.remaining }} 魅力值，成为{{ summary.level.nextLevel.name }}</text>
				<text v-else class="next-level">已抵达最高魅力等级</text>
			</view>
			<view class="hero-stats">
				<view><text class="strip-value">{{ summary.totalReceived }}</text><text class="strip-label">累计收获</text></view>
				<view class="strip-line" />
				<view><text class="strip-value">{{ summary.recordCount || summary.records.length }}</text><text class="strip-label">温暖记录</text></view>
				<view class="strip-line" />
				<view><text class="strip-value withdraw-stat-value">{{ summary.balance }}/{{ withdrawal.minimumValue }}</text><text class="strip-label">提现门槛</text></view>
			</view>
			<button
				class="hero-withdraw-button"
				:class="{ disabled: !canWithdraw }"
				:disabled="!canWithdraw"
				@click="openWithdrawal"
			>{{ withdrawButtonText }}</button>
		</view>

		<view class="content">
			<view class="section-head first-section-head"><text>魅力权益</text></view>
			<view class="benefit-grid">
				<view v-for="(benefit, index) in summary.benefits" :key="benefit.title" class="benefit-card">
					<view class="benefit-icon" :class="benefitClass(index)">{{ benefitIcon(index) }}</view>
					<text class="benefit-title">{{ benefit.title }}</text>
				</view>
			</view>
			<view class="section-head"><text>魅力等级</text><text>{{ summary.level.name }}</text></view>
			<scroll-view class="level-scroll" scroll-x :show-scrollbar="false">
				<view class="level-row">
					<view v-for="level in summary.levels" :key="level.code" class="level-node" :class="{ active: summary.balance >= level.minValue }">
						<view class="level-dot">{{ summary.balance >= level.minValue ? '✓' : '·' }}</view>
						<text>{{ level.name }}</text><text>{{ level.minValue }}+</text>
					</view>
				</view>
			</scroll-view>

			<view class="section-head"><text>温暖明细</text><text>最近 20 条</text></view>
			<view class="record-list">
				<view v-if="loading" class="empty-state">正在加载</view>
				<view v-else-if="!visibleRecords.length" class="empty-state">收到礼物后，这里会留下温暖的记录</view>
				<view v-for="record in visibleRecords" :key="record.id" class="record-row">
					<view class="record-icon">♥</view>
					<view class="record-copy"><text>{{ record.description }}</text><text>{{ formatTime(record.createdAt) }}</text></view>
					<text class="record-amount" :class="{ spend: record.amount < 0 }">{{ record.amount > 0 ? '+' : '' }}{{ record.amount }}</text>
				</view>
			</view>
		</view>

		<view v-if="withdrawalVisible" class="withdraw-modal-mask" @click="closeWithdrawal">
			<view class="withdraw-modal" @click.stop>
				<view class="withdraw-modal-head">
					<text class="withdraw-modal-title">申请提现</text>
					<view class="withdraw-modal-close" @click="closeWithdrawal">×</view>
				</view>
				<template v-if="withdrawal.customerServiceQrUrl">
					<image
						class="withdraw-qr"
						:src="withdrawal.customerServiceQrUrl"
						mode="aspectFit"
						show-menu-by-longpress
						@click="previewWithdrawalQr"
					/>
					<text class="withdraw-modal-copy">长按识别二维码，联系客服提交提现资料</text>
				</template>
				<template v-else>
					<view class="withdraw-qr-empty">客服</view>
					<text class="withdraw-modal-copy">客服二维码尚未配置，请先联系在线客服</text>
					<button class="contact-button" open-type="contact">联系在线客服</button>
				</template>
			</view>
		</view>
	</view>
</template>

<script>
import { fetchCharmSummary } from '../../api/user';
import { showRequestError } from '../../utils/feedback';

const EMPTY_SUMMARY = {
	balance: 0,
	recordCount: 0,
	totalReceived: 0,
	level: { name: '微光初现', description: '每一份心意，都值得被看见。', progress: 0, remaining: 100, nextLevel: { name: '温柔回响' } },
	levels: [],
	benefits: [],
	records: [],
	withdrawal: { minimumValue: 500, eligible: false, remaining: 500, customerServiceQrUrl: '' }
};

export default {
	data() {
		return { loading: false, statusBarHeight: 24, withdrawalVisible: false, summary: { ...EMPTY_SUMMARY } };
	},
	computed: {
		visibleRecords() {
			return Array.isArray(this.summary.records) ? this.summary.records.slice(0, 20) : [];
		},
		progressStyle() {
			return `width: ${Math.max(0, Math.min(100, Number(this.summary.level.progress || 0)))}%;`;
		},
		withdrawal() {
			return this.summary.withdrawal || EMPTY_SUMMARY.withdrawal;
		},
		canWithdraw() {
			return !this.loading && Number(this.summary.balance || 0) >= Number(this.withdrawal.minimumValue || 500);
		},
		withdrawButtonText() {
			return this.loading ? '余额加载中' : '申请提现';
		}
	},
	onLoad() {
		const systemInfo = uni.getSystemInfoSync();
		this.statusBarHeight = Number(systemInfo.statusBarHeight || 24);
	},
	onShow() { this.loadData(); },
	methods: {
		async loadData() {
			this.loading = true;
			try {
				const result = await fetchCharmSummary();
				this.summary = {
					...EMPTY_SUMMARY,
					...result,
					recordCount: Number(result && result.recordCount) || (Array.isArray(result && result.records) ? result.records.length : 0),
					level: { ...EMPTY_SUMMARY.level, ...(result && result.level) },
					withdrawal: { ...EMPTY_SUMMARY.withdrawal, ...(result && result.withdrawal) },
					levels: Array.isArray(result && result.levels) ? result.levels : [],
					benefits: Array.isArray(result && result.benefits) ? result.benefits : [],
					records: Array.isArray(result && result.records) ? result.records : []
				};
			} catch (error) {
				showRequestError(error, '魅力值加载失败');
			} finally {
				this.loading = false;
			}
		},
		formatTime(value) {
			const date = new Date(value);
			if (Number.isNaN(date.getTime())) return '';
			return `${date.getMonth() + 1}月${date.getDate()}日 ${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
		},
		benefitClass(index) {
			return `benefit-${Number(index || 0)}`;
		},
		benefitIcon(index) {
			return ['✦', '♥', '∞', '¥'][Number(index || 0)] || '✦';
		},
		openWithdrawal() {
			if (!this.canWithdraw) return;
			this.withdrawalVisible = true;
		},
		closeWithdrawal() {
			this.withdrawalVisible = false;
		},
		previewWithdrawalQr() {
			const url = this.withdrawal.customerServiceQrUrl;
			if (!url) return;
			uni.previewImage({ current: url, urls: [url] });
		},
		goBack() {
			uni.navigateBack({
				fail: () => uni.switchTab({ url: '/pages/profile/index' })
			});
		}
	}
};
</script>

